export function setCachedResult(
  cache: AnalysisCache,
  functionId: string,
  contentHash: string,
  result: AnalysisResult,
  provider: string,
  model: string
): void {
  const entry: AnalysisCacheEntry = {
    contentHash,
    result,
    analyzedAt: new Date().toISOString(),
    provider,
    model,
  };

  cache.entries[functionId] = entry;
  cache.updatedAt = new Date().toISOString();
}

