async function processWithConcurrency<T, R>(
  items: T[],
  concurrency: number,
  processor: (item: T, index: number) => Promise<R>
): Promise<R[]> {
  const results: R[] = [];
  let index = 0;

  async function worker(): Promise<void> {
    while (index < items.length) {
      const currentIndex = index++;
      const item = items[currentIndex]!;
      results[currentIndex] = await processor(item, currentIndex);
    }
  }

  // Start workers up to concurrency limit
  const workers = Array(Math.min(concurrency, items.length))
    .fill(null)
    .map(() => worker());

  await Promise.all(workers);
  return results;
}

function extractFunctionCode(
  filePath: string,
  startLine: number,
  endLine: number
): string {
  try {
    const content = readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');
    // Line numbers are 1-indexed
    return lines.slice(startLine - 1, endLine).join('\n');
  } catch {
    return '';
  }
}

export async function analyzeBehavior(
  scanResult: ScanResult,
  provider: LLMProvider,
  options: AnalyzeOptions = {}
): Promise<ScanResult> {
  const {
    onProgress,
    skipAnalyzed = true,
    maxFunctions,
    cacheDir,
    concurrency = 5,
  } = options;

  // The cache is keyed on the active provider + model so a backend/model swap
  // invalidates summaries produced by the previous one.
  const providerName = provider.name;
  const model = provider.model;

  // Load or create cache
  let cache: AnalysisCache | null = null;
  if (cacheDir) {
    cache = loadCache(cacheDir) || createCache(scanResult.projectPath);
  }

  // Collect all function nodes that need analysis
  const functionsToAnalyze: FunctionNode[] = [];

  for (const node of Object.values(scanResult.nodes)) {
    if (node.type === NodeType.Function) {
      const funcNode = node as FunctionNode;
      // Skip if already analyzed and skipAnalyzed is true
      if (skipAnalyzed && funcNode.behavioral) {
        continue;
      }
      functionsToAnalyze.push(funcNode);
    }
  }

  // Apply max functions limit
  const targetFunctions = maxFunctions
    ? functionsToAnalyze.slice(0, maxFunctions)
    : functionsToAnalyze;

  const total = targetFunctions.length;
  let completed = 0;
  let analyzedCount = scanResult.stats.analyzedCount || 0;

  // Process functions with concurrency
  await processWithConcurrency(
    targetFunctions,
    concurrency,
    async (funcNode, _index) => {
      // Extract function code
      const code = extractFunctionCode(
        funcNode.filePath,
        funcNode.line,
        funcNode.endLine
      );

      if (!code) {
        completed++;
        return;
      }

      const contentHash = hashFunctionContent(code);

      // Check cache first
      if (cache) {
        const cachedResult = getCachedResult(cache, funcNode.id, contentHash, providerName, model);
        if (cachedResult) {
          funcNode.behavioral = {
            summary: cachedResult.summary,
            source: 'ai' as SummarySource,
            analyzedAt: new Date().toISOString(),
            flags: cachedResult.flags,
          };
          analyzedCount++;
          completed++;

          if (onProgress) {
            onProgress({
              current: completed,
              total,
              functionName: funcNode.name,
              filePath: funcNode.filePath,
              fromCache: true,
            });
          }
          return;
        }
      }

      // Report progress (will call LLM)
      if (onProgress) {
        onProgress({
          current: completed,
          total,
          functionName: funcNode.name,
          filePath: funcNode.filePath,
          fromCache: false,
        });
      }

      try {
        // Call the provider for analysis
        const result = await provider.describeFunction({
          functionName: funcNode.name,
          functionCode: code,
          filePath: funcNode.filePath,
        });

        funcNode.behavioral = {
          summary: result.summary,
          source: 'ai' as SummarySource,
          analyzedAt: new Date().toISOString(),
          flags: result.flags,
        };

        if (cache) {
          setCachedResult(cache, funcNode.id, contentHash, result, providerName, model);
        }

        analyzedCount++;
      } catch (error) {
        console.error(
          `Failed to analyze ${funcNode.name} in ${funcNode.filePath}:`,
          error instanceof Error ? error.message : error
        );
      }

      completed++;
    }
  );

  // Save cache if we have one
  if (cache && cacheDir) {
    saveCache(cacheDir, cache);
  }

  // Update stats
  scanResult.stats.analyzedCount = analyzedCount;
  scanResult.stats.pendingAnalysis = functionsToAnalyze.length - analyzedCount;

  return scanResult;
}

export async function analyzeSingleFunction(
  funcNode: FunctionNode,
  provider: LLMProvider
): Promise<FunctionNode> {
  const code = extractFunctionCode(
    funcNode.filePath,
    funcNode.line,
    funcNode.endLine
  );

  if (!code) {
    throw new Error(`Could not extract code for ${funcNode.name}`);
  }

  const result = await provider.describeFunction({
    functionName: funcNode.name,
    functionCode: code,
    filePath: funcNode.filePath,
  });

  funcNode.behavioral = {
    summary: result.summary,
    source: 'ai' as SummarySource,
    analyzedAt: new Date().toISOString(),
    flags: result.flags,
  };

  return funcNode;
}

