function stripJsonComments(content: string): string {
  const result: string[] = [];
  let i = 0;
  let inString = false;
  let inLineComment = false;
  let inBlockComment = false;

  while (i < content.length) {
    const char = content[i]!;
    const nextChar = content[i + 1];

    // Handle string boundaries (only when not in a comment)
    if (!inLineComment && !inBlockComment) {
      if (char === '"' && (i === 0 || content[i - 1] !== '\\')) {
        inString = !inString;
        result.push(char);
        i++;
        continue;
      }
    }

    // When inside a string, just copy characters
    if (inString) {
      result.push(char);
      i++;
      continue;
    }

    // Handle line comment start
    if (!inBlockComment && char === '/' && nextChar === '/') {
      inLineComment = true;
      i += 2;
      continue;
    }

    // Handle line comment end (newline)
    if (inLineComment && (char === '\n' || char === '\r')) {
      inLineComment = false;
      result.push(char); // Keep the newline
      i++;
      continue;
    }

    // Handle block comment start
    if (!inLineComment && char === '/' && nextChar === '*') {
      inBlockComment = true;
      i += 2;
      continue;
    }

    // Handle block comment end
    if (inBlockComment && char === '*' && nextChar === '/') {
      inBlockComment = false;
      i += 2;
      continue;
    }

    // Skip characters inside comments
    if (inLineComment || inBlockComment) {
      i++;
      continue;
    }

    // Regular character - copy it
    result.push(char);
    i++;
  }

  return result.join('');
}

