export async function scanProject(
  projectPath: string,
  options: ScanOptions = {}
): Promise<ScanResult> {
  const { verbose = false, onProgress } = options;
  const absolutePath = path.resolve(projectPath);
  const scanId = uuidv4();
  const startTime = new Date().toISOString();

  if (verbose) {
    console.log(`Starting scan of: ${absolutePath}`);
  }

  // Initialize result structure
  const errors: ScanError[] = [];
  const nodes: NodeMap = {};

  // Find all source files
  const sourceFilePaths = await findSourceFiles(absolutePath);

  if (verbose) {
    console.log(`Found ${sourceFilePaths.length} source files`);
  }

  // Create ts-morph Project
  const project = new Project({
    skipAddingFilesFromTsConfig: true,
    skipFileDependencyResolution: true,
  });

  // Add source files to project
  for (const filePath of sourceFilePaths) {
    try {
      project.addSourceFileAtPath(filePath);
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      errors.push({
        filePath: path.relative(absolutePath, filePath),
        line: null,
        message: `Failed to add file: ${error}`,
        recoverable: true,
      });
    }
  }

  // Parse each source file
  const sourceFiles = project.getSourceFiles();
  const totalFiles = sourceFiles.length;
  let fileIndex = 0;

  for (const sourceFile of sourceFiles) {
    const filePath = sourceFile.getFilePath();
    const relativePath = path.relative(absolutePath, filePath);

    // Emit progress before parsing
    if (onProgress) {
      onProgress({
        phase: 'scanning',
        current: fileIndex + 1,
        total: totalFiles,
        filePath: relativePath,
      });
    }

    try {
      const { fileNode, functionNodes, classNodes } = parseSourceFile(
        sourceFile,
        absolutePath,
        errors
      );

      // Add file node
      nodes[fileNode.id] = fileNode;

      // Add function nodes
      for (const fn of functionNodes) {
        nodes[fn.id] = fn;
      }

      // Add class nodes
      for (const cls of classNodes) {
        nodes[cls.id] = cls;
      }

      if (verbose) {
        console.log(`  Parsed: ${fileNode.filePath} (${functionNodes.length} functions, ${classNodes.length} classes)`);
      }
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      errors.push({
        filePath: relativePath,
        line: null,
        message: `Failed to parse file: ${error}`,
        recoverable: true,
      });
    }

    fileIndex++;
  }

  // Read path aliases from tsconfig.json (needed by both connections and warnings)
  const pathAliases = readPathAliases(absolutePath);
  if (verbose && Object.keys(pathAliases).length > 0) {
    console.log(`  Found path aliases: ${Object.keys(pathAliases).join(', ')}`);
  }

  // Build connection graph
  const connections = buildConnections(nodes, pathAliases);
  if (verbose) {
    console.log(`  Built ${connections.length} connections`);
  }

  // Calculate statistics
  const stats = calculateStats(nodes);
  stats.totalConnections = connections.length;

  // Build final result
  const result: ScanResult = {
    id: scanId,
    projectPath: absolutePath,
    projectName: getProjectName(absolutePath),
    status: errors.length > 0 && Object.keys(nodes).length === 0
      ? ScanStatus.Failed
      : ScanStatus.Complete,
    createdAt: startTime,
    completedAt: new Date().toISOString(),
    stats,
    nodes,
    connections,
    warnings: [],    // Populated below
    clusters: [],    // Phase 7: Build clusters
    errors,
  };

  // Detect warnings (unless skipped)
  if (!options.skipWarnings) {
    if (verbose) {
      console.log(`\nDetecting warnings...`);
    }

    // Merge path aliases with user-provided options
    const warningOptions: WarningDetectorOptions = {
      ...options.warningOptions,
      pathAliases: {
        ...pathAliases,
        ...options.warningOptions?.pathAliases,
      },
    };

    result.warnings = await detectWarnings(result, warningOptions);
    updateWarningStats(result);

    if (verbose) {
      console.log(`  Found ${result.warnings.length} in-process warnings (large_file)`);
    }

    // External detection engines (knip + dependency-cruiser) — trustworthy
    // problem-flagging. Best-effort: a failing engine is recorded, not fatal.
    if (options.detection) {
      if (verbose) {
        console.log(`\nRunning detection engines (knip + dependency-cruiser)...`);
      }
      const external = await runExternalDetection(absolutePath, nodes, options.detection);
      result.warnings.push(...external.warnings);
      for (const engErr of external.engineErrors) {
        errors.push({
          filePath: '.',
          line: null,
          message: `Detection engine "${engErr.engine}" failed: ${engErr.message}`,
          recoverable: true,
        });
      }
      updateWarningStats(result);

      if (verbose) {
        console.log(
          `  Detection engines added ${external.warnings.length} warnings` +
            (external.engineErrors.length ? ` (${external.engineErrors.length} engine error(s))` : '')
        );
      }
    }
  }

  if (verbose) {
    console.log(`\nScan complete:`);
    console.log(`  Files: ${stats.totalFiles}`);
    console.log(`  Functions: ${stats.totalFunctions}`);
    console.log(`  Classes: ${stats.totalClasses}`);
    console.log(`  Warnings: ${result.stats.totalWarnings}`);
    console.log(`  Errors: ${errors.length}`);
  }

  return result;
}

